package types

// Well-known preinstall contract addresses (matching Ethereum mainnet)
const (
	// Multicall3Address is the address of the Multicall3 contract
	Multicall3Address = "0xcA11bde05977b3631167028862bE2a173976CA11"
	// Create2DeployerAddress is the address of the Create2Deployer (deterministic deployment proxy)
	Create2DeployerAddress = "0x4e59b44847b379578588920cA78FbF26c0B4956C"
)

// Multicall3Bin is the runtime bytecode of the Multicall3 contract.
// Source: https://www.multicall3.com/
var Multicall3Bin = ""

// Create2DeployerBin is the runtime bytecode of the deterministic deployment proxy.
// Source: https://github.com/Arachnid/deterministic-deployment-proxy
var Create2DeployerBin = "7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffe03601600081602082378035828234f58015156039578182fd5b8082525050506014600cf3"

// DefaultPreinstalls returns the default preinstall contracts for the chain.
func DefaultPreinstalls() []Preinstall {
	return []Preinstall{
		{
			Name:    "Multicall3",
			Address: Multicall3Address,
			Code:    Multicall3Bin,
		},
		{
			Name:    "Create2Deployer",
			Address: Create2DeployerAddress,
			Code:    Create2DeployerBin,
		},
	}
}
